#!/usr/bin/env node
// scripts/build-hpke-bundle.mjs - rebuild the vendored browser HPKE sealer (secure moments W2).
//
//   mkdir /tmp/hpke && cd /tmp/hpke && npm init -y && \
//     npm install --save-exact @hpke/core@1.9.0 @hpke/dhkem-x25519@1.8.0 esbuild@0.25.5
//   node scripts/build-hpke-bundle.mjs /tmp/hpke
//
// Bundles scripts/vendor/hpke-seal.entry.mjs into ONE minified IIFE (global MupotHpke), prefixes a version header,
// and writes both src/secure-drop/vendor/hpke-seal.v1.js (the reviewable artifact) and
// src/secure-drop/hpke-bundle.generated.ts (the same bytes as a string a Worker can serve, plus sha256 and the
// SRI sha384). The Worker serves it from the secure host itself; there is no CDN. tests/secure-drop.test.ts pins
// the sha256 against docs/architecture/secure-moments.md, so a changed bundle fails CI until the doc is updated.
import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(fileURLToPath(new URL('.', import.meta.url)), '..')
const dir = process.argv[2]
if (!dir) { console.error('usage: build-hpke-bundle.mjs <dir containing node_modules with the pinned packages>'); process.exit(2) }
const PINS = { '@hpke/core': '1.9.0', '@hpke/dhkem-x25519': '1.8.0', '@hpke/common': '1.10.1', esbuild: '0.25.5' }
for (const [pkg, want] of Object.entries(PINS)) {
  const got = JSON.parse(readFileSync(join(dir, 'node_modules', pkg, 'package.json'), 'utf8')).version
  if (got !== want) { console.error(`${pkg} is ${got}, expected ${want}`); process.exit(1) }
}
const entry = join(ROOT, 'scripts', 'vendor', 'hpke-seal.entry.mjs')
const tmpEntry = join(dir, 'entry.mjs')
writeFileSync(tmpEntry, readFileSync(entry))
const out = execFileSync(join(dir, 'node_modules', '.bin', 'esbuild'), [
  tmpEntry, '--bundle', '--minify', '--format=iife', '--global-name=MupotHpke', '--target=es2022', '--legal-comments=none',
], { cwd: dir, encoding: 'utf8' })
const header = `/* mupot-hpke-bundle v1 | HPKE RFC 9180 base, DHKEM(X25519,HKDF-SHA256)/HKDF-SHA256/AES-128-GCM | @hpke/core ${PINS['@hpke/core']} @hpke/dhkem-x25519 ${PINS['@hpke/dhkem-x25519']} @hpke/common ${PINS['@hpke/common']} | esbuild ${PINS.esbuild} | source: scripts/vendor/hpke-seal.entry.mjs */\n`
const js = header + out
writeFileSync(join(ROOT, 'src', 'secure-drop', 'vendor', 'hpke-seal.v1.js'), js)
const sha256 = createHash('sha256').update(js).digest('hex')
const sri = `sha384-${createHash('sha384').update(js).digest('base64')}`
writeFileSync(join(ROOT, 'src', 'secure-drop', 'hpke-bundle.generated.ts'),
  `// GENERATED by scripts/build-hpke-bundle.mjs from src/secure-drop/vendor/hpke-seal.v1.js. Do not edit.\n` +
  `export const HPKE_BUNDLE_JS = ${JSON.stringify(js)}\n` +
  `export const HPKE_BUNDLE_SHA256 = ${JSON.stringify(sha256)}\n` +
  `export const HPKE_BUNDLE_SRI = ${JSON.stringify(sri)}\n`)
console.log(`sha256 ${sha256}\nsri ${sri}\nbytes ${Buffer.byteLength(js)}`)
